// @prop startSceneId scene scene_level_1
function getManager(engine) {
  return (engine && engine.sceneManager) || (typeof sceneManager !== 'undefined' ? sceneManager : null) || window.sceneManager;
}

function getStorage(engine) {
  return (engine && engine.storage) || null;
}

function readSettings(engine) {
  var storage = getStorage(engine);
  return storage && typeof storage.load === 'function' ? (storage.load('settings') || {}) : {};
}

function readProgress(engine) {
  var storage = getStorage(engine);
  return storage && typeof storage.load === 'function' ? storage.load('progress') : null;
}

function applyVolume(engine) {
  var settings = readSettings(engine);
  var volume = Number(settings && settings.volume);
  var next = Number.isFinite(volume) ? Math.max(0, Math.min(1, volume)) : 0.55;
  if (engine && engine.audio && typeof engine.audio.setMasterVolume === 'function') {
    engine.audio.setMasterVolume(next);
  }
  self.currentVolume = next;
}

function persistVolume(engine, value) {
  var storage = getStorage(engine);
  var next = Math.max(0, Math.min(1, Number(value) || 0));
  if (engine && engine.audio && typeof engine.audio.setMasterVolume === 'function') {
    engine.audio.setMasterVolume(next);
  }
  if (storage && typeof storage.save === 'function') {
    storage.save({ volume: next }, 'settings');
  }
  self.currentVolume = next;
}

function onInit(self, engine) {
  applyVolume(engine);
  var manager = (engine && engine.uiManager) || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_menu', {
    layer: 'hud',
    layerOrder: 100,
    isVisible: function() { return true; },
    create: function() {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at top, rgba(251,191,36,0.18), rgba(2,6,23,0.94));pointer-events:auto;font-family:Trebuchet MS,sans-serif;';
      var card = document.createElement('div');
      card.style.cssText = 'width:min(560px,92vw);padding:28px 26px;border-radius:22px;background:rgba(15,23,42,0.96);border:1px solid rgba(148,163,184,0.24);box-shadow:0 24px 90px rgba(0,0,0,0.46);color:#e2e8f0;';
      var title = document.createElement('h1');
      title.textContent = 'Adventure Platformer';
      title.style.cssText = 'margin:0 0 8px;font-size:34px;letter-spacing:0.02em;';
      var subtitle = document.createElement('p');
      subtitle.textContent = 'Five connected levels, one dark cavern, goal portals that save your progress.';
      subtitle.style.cssText = 'margin:0 0 18px;color:#cbd5e1;line-height:1.55;';
      var actions = document.createElement('div');
      actions.style.cssText = 'display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px;';
      var startBtn = document.createElement('button');
      startBtn.textContent = 'Start New Run';
      startBtn.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#facc15;color:#422006;font-weight:700;cursor:pointer;';
      startBtn.onclick = function() {
        var manager = getManager(engine);
        var storage = getStorage(engine);
        var startSceneId = props.startSceneId || 'scene_level_1';
        if (storage && typeof storage.save === 'function') {
          storage.save({ sceneId: startSceneId, updatedAt: Date.now() }, 'progress');
        }
        if (manager && typeof manager.loadScene === 'function') manager.loadScene(startSceneId);
      };
      var continueBtn = document.createElement('button');
      continueBtn.id = self.id + '_continue';
      continueBtn.textContent = 'Continue Save';
      continueBtn.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#38bdf8;color:#082f49;font-weight:700;cursor:pointer;';
      continueBtn.onclick = function() {
        var manager = getManager(engine);
        var save = readProgress(engine);
        var target = save && save.sceneId ? save.sceneId : (props.startSceneId || 'scene_level_1');
        if (manager && typeof manager.loadScene === 'function') manager.loadScene(target);
      };
      var clearBtn = document.createElement('button');
      clearBtn.textContent = 'Clear Save';
      clearBtn.style.cssText = 'padding:12px 18px;border:1px solid rgba(248,250,252,0.14);border-radius:999px;background:rgba(15,23,42,0.8);color:#f8fafc;font-weight:700;cursor:pointer;';
      clearBtn.onclick = function() {
        var storage = getStorage(engine);
        if (storage && typeof storage.clear === 'function') storage.clear('progress');
      };
      actions.appendChild(startBtn);
      actions.appendChild(continueBtn);
      actions.appendChild(clearBtn);
      var settingsTitle = document.createElement('div');
      settingsTitle.textContent = 'Settings';
      settingsTitle.style.cssText = 'margin:0 0 8px;font-size:13px;font-weight:700;color:#fde68a;letter-spacing:0.06em;text-transform:uppercase;';
      var volumeWrap = document.createElement('label');
      volumeWrap.style.cssText = 'display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;background:rgba(30,41,59,0.78);';
      var volumeLabel = document.createElement('span');
      volumeLabel.textContent = 'Master Volume';
      volumeLabel.style.cssText = 'min-width:110px;font-size:13px;';
      var slider = document.createElement('input');
      slider.id = self.id + '_volume';
      slider.type = 'range';
      slider.min = '0';
      slider.max = '1';
      slider.step = '0.01';
      slider.value = String(self.currentVolume || 0.55);
      slider.style.cssText = 'flex:1;';
      slider.oninput = function(event) {
        persistVolume(engine, event.target.value);
      };
      var volumeReadout = document.createElement('span');
      volumeReadout.id = self.id + '_volume_text';
      volumeReadout.style.cssText = 'min-width:48px;text-align:right;font-variant-numeric:tabular-nums;color:#fde68a;font-size:12px;';
      volumeWrap.appendChild(volumeLabel);
      volumeWrap.appendChild(slider);
      volumeWrap.appendChild(volumeReadout);
      var status = document.createElement('p');
      status.id = self.id + '_status';
      status.style.cssText = 'margin:16px 0 0;color:#94a3b8;line-height:1.5;font-size:12px;';
      status.textContent = 'Progress auto-saves whenever you reach a goal portal.';
      card.appendChild(title);
      card.appendChild(subtitle);
      card.appendChild(actions);
      card.appendChild(settingsTitle);
      card.appendChild(volumeWrap);
      card.appendChild(status);
      wrap.appendChild(card);
      return wrap;
    },
    update: function() {
      applyVolume(engine);
      var slider = document.getElementById(self.id + '_volume');
      var volumeText = document.getElementById(self.id + '_volume_text');
      var status = document.getElementById(self.id + '_status');
      var continueBtn = document.getElementById(self.id + '_continue');
      var save = readProgress(engine);
      if (slider) slider.value = String(self.currentVolume || 0.55);
      if (volumeText) volumeText.textContent = Math.round((self.currentVolume || 0) * 100) + '%';
      if (continueBtn) {
        continueBtn.disabled = !(save && save.sceneId);
        continueBtn.style.opacity = save && save.sceneId ? '1' : '0.45';
        continueBtn.style.cursor = save && save.sceneId ? 'pointer' : 'not-allowed';
      }
      if (status) {
        status.textContent = save && save.sceneId
          ? 'Saved scene: ' + save.sceneId + '. Progress auto-saves whenever you reach a portal.'
          : 'No saved run yet. Start a new run and each portal will save the next scene.';
      }
    }
  });
}

function onUpdate(self, engine, dt) {
  // UI manager drives the menu screen.
}

// @prop levelName string Meadow Hop
// @prop menuSceneId scene scene_menu
function getStorage(engine) {
  return (engine && engine.storage) || null;
}

function applyVolume(engine) {
  var storage = getStorage(engine);
  var settings = storage && typeof storage.load === 'function' ? (storage.load('settings') || {}) : {};
  var volume = Number(settings && settings.volume);
  var next = Number.isFinite(volume) ? Math.max(0, Math.min(1, volume)) : 0.55;
  if (engine && engine.audio && typeof engine.audio.setMasterVolume === 'function') engine.audio.setMasterVolume(next);
}

function onInit(self, engine) {
  applyVolume(engine);
  var manager = (engine && engine.uiManager) || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_hud', {
    layer: 'hud',
    layerOrder: 10,
    isVisible: function() { return true; },
    create: function() {
      var panel = document.createElement('div');
      panel.style.cssText = 'position:absolute;left:16px;top:16px;padding:12px 14px;border-radius:16px;background:rgba(15,23,42,0.76);color:#e2e8f0;font-family:Trebuchet MS,sans-serif;pointer-events:none;min-width:220px;box-shadow:0 14px 50px rgba(2,6,23,0.35);';
      panel.innerHTML = '<div id="' + self.id + '_name" style="font-size:15px;font-weight:700;"></div><div id="' + self.id + '_pos" style="margin-top:4px;font-size:12px;color:#93c5fd;"></div><div style="margin-top:6px;font-size:11px;color:#94a3b8;">WASD / Arrows / Space to move, M for menu, portals auto-save.</div>';
      return panel;
    },
    update: function() {
      var player = engine && typeof engine.findObject === 'function' ? engine.findObject('obj_player') : null;
      var name = document.getElementById(self.id + '_name');
      var pos = document.getElementById(self.id + '_pos');
      if (name) name.textContent = props.levelName || 'Level';
      if (pos && player) pos.textContent = 'Player ' + Math.round(player.x) + ', ' + Math.round(player.y);
    }
  });
}

function onUpdate(self, engine, dt) {
  var manager = (engine && engine.sceneManager) || (typeof sceneManager !== 'undefined' ? sceneManager : null) || window.sceneManager;
  var menuDown = keyIsDown(77);
  if (menuDown && !self.menuLatch && manager && typeof manager.loadScene === 'function') {
    manager.loadScene(props.menuSceneId || 'scene_menu');
  }
  self.menuLatch = menuDown;
}

function overlaps(a, b) {
  return !!(a && b && a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y);
}

function cellTypeId(cell) {
  if (cell == null) return 'empty';
  if (typeof cell === 'string') return cell;
  if (typeof cell === 'object') return cell.typeId || cell.id || 'empty';
  return String(cell);
}

function touchesType(self, engine, typeId) {
  var world = engine && engine.world;
  if (!world || typeof world.sampleCell !== 'function') return false;
  var cellSize = world.cellSize || 24;
  var left = Math.floor((self.x + 2) / cellSize);
  var right = Math.floor((self.x + self.width - 2) / cellSize);
  var top = Math.floor((self.y + 2) / cellSize);
  var bottom = Math.floor((self.y + self.height - 2) / cellSize);
  for (var cy = top; cy <= bottom; cy += 1) {
    for (var cx = left; cx <= right; cx += 1) {
      if (cellTypeId(world.sampleCell(cx, cy)) === typeId) return true;
    }
  }
  return false;
}

function respawn(self) {
  self.x = self.spawnX;
  self.y = self.spawnY;
  self.vx = 0;
  self.vy = 0;
  self.grounded = false;
}

function onInit(self, engine) {
  self.spawnX = self.x;
  self.spawnY = self.y;
  self.vx = 0;
  self.vy = 0;
  self.grounded = false;
  self.jumpLatch = false;
}

function onUpdate(self, engine, dt) {
  var world = engine && engine.world;
  var wasGrounded = !!self.grounded;
  var moveLeft = keyIsDown(65) || keyIsDown(37);
  var moveRight = keyIsDown(68) || keyIsDown(39);
  var jumpDown = keyIsDown(32) || keyIsDown(87) || keyIsDown(38);
  var move = (moveRight ? 1 : 0) - (moveLeft ? 1 : 0);

  self.vx = move * 188;
  if (jumpDown && wasGrounded && !self.jumpLatch) {
    self.vy = -390;
  }
  self.jumpLatch = jumpDown;
  self.grounded = false;
  self.vy = Math.min(620, self.vy + (980 * dt));
  self.x += self.vx * dt;
  self.y += self.vy * dt;

  if (world) {
    self.x = Math.max(world.minX || 0, Math.min(self.x, (world.maxX || 0) - self.width));
  }
  if ((world && self.y > (world.maxY + 160)) || touchesType(self, engine, 'hazard')) {
    respawn(self);
  }
}

// @prop nextSceneId scene scene_level_2
function overlaps(a, b) {
  return !!(a && b && a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y);
}

function onInit(self, engine) {
  self.triggered = false;
  self.timer = 0;
}

function onUpdate(self, engine, dt) {
  var player = engine && typeof engine.findObject === 'function' ? engine.findObject('obj_player') : null;
  var manager = (engine && engine.sceneManager) || (typeof sceneManager !== 'undefined' ? sceneManager : null) || window.sceneManager;
  var storage = (engine && engine.storage) || null;
  if (!self.triggered && overlaps(self, player)) {
    self.triggered = true;
    self.timer = 0.42;
    if (engine && engine.particles && typeof engine.particles.emitObject === 'function') {
      engine.particles.emitObject(self, { count: 48, speed: 150, life: 760, size: 7, sizeEnd: 1 });
    }
    if (engine && engine.audio && typeof engine.audio.playObjectSound === 'function') {
      engine.audio.playObjectSound(self);
    }
    if (storage && typeof storage.save === 'function') {
      storage.save({ sceneId: props.nextSceneId || null, updatedAt: Date.now() }, 'progress');
    }
    if (self.components && self.components.Render) self.components.Render.visible = false;
  }
  if (!self.triggered) return;
  self.timer -= dt;
  if (self.timer > 0) return;
  self.triggered = false;
  if (manager && props.nextSceneId && typeof manager.loadScene === 'function') {
    manager.loadScene(props.nextSceneId);
    return;
  }
  if (manager && typeof manager.loadNextScene === 'function') manager.loadNextScene();
}

// @prop title string Summit Reached
// @prop replaySceneId scene scene_level_1
// @prop menuSceneId scene scene_menu
function getStorage(engine) {
  return (engine && engine.storage) || null;
}

function applyVolume(engine) {
  var storage = getStorage(engine);
  var settings = storage && typeof storage.load === 'function' ? (storage.load('settings') || {}) : {};
  var volume = Number(settings && settings.volume);
  var next = Number.isFinite(volume) ? Math.max(0, Math.min(1, volume)) : 0.55;
  if (engine && engine.audio && typeof engine.audio.setMasterVolume === 'function') engine.audio.setMasterVolume(next);
}

function onInit(self, engine) {
  applyVolume(engine);
  var manager = (engine && engine.uiManager) || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_victory', {
    layer: 'hud',
    layerOrder: 100,
    isVisible: function() { return true; },
    create: function() {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at top, rgba(34,197,94,0.18), rgba(2,6,23,0.94));pointer-events:auto;font-family:Trebuchet MS,sans-serif;';
      var card = document.createElement('div');
      card.style.cssText = 'width:min(520px,92vw);padding:28px 26px;border-radius:22px;background:rgba(15,23,42,0.96);border:1px solid rgba(148,163,184,0.24);box-shadow:0 24px 90px rgba(0,0,0,0.46);color:#e2e8f0;';
      var title = document.createElement('h1');
      title.textContent = props.title || 'Summit Reached';
      title.style.cssText = 'margin:0 0 10px;font-size:34px;';
      var text = document.createElement('p');
      text.textContent = 'The full five-level run is complete. Start over or return to the menu.';
      text.style.cssText = 'margin:0 0 18px;color:#cbd5e1;line-height:1.5;';
      var actions = document.createElement('div');
      actions.style.cssText = 'display:flex;gap:10px;flex-wrap:wrap;';
      var replayBtn = document.createElement('button');
      replayBtn.textContent = 'Replay Run';
      replayBtn.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#22c55e;color:#052e16;font-weight:700;cursor:pointer;';
      replayBtn.onclick = function() {
        var storage = getStorage(engine);
        var manager = (engine && engine.sceneManager) || (typeof sceneManager !== 'undefined' ? sceneManager : null) || window.sceneManager;
        var target = props.replaySceneId || 'scene_level_1';
        if (storage && typeof storage.save === 'function') storage.save({ sceneId: target, updatedAt: Date.now() }, 'progress');
        if (manager && typeof manager.loadScene === 'function') manager.loadScene(target);
      };
      var menuBtn = document.createElement('button');
      menuBtn.textContent = 'Main Menu';
      menuBtn.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#38bdf8;color:#082f49;font-weight:700;cursor:pointer;';
      menuBtn.onclick = function() {
        var manager = (engine && engine.sceneManager) || (typeof sceneManager !== 'undefined' ? sceneManager : null) || window.sceneManager;
        if (manager && typeof manager.loadScene === 'function') manager.loadScene(props.menuSceneId || 'scene_menu');
      };
      actions.appendChild(replayBtn);
      actions.appendChild(menuBtn);
      card.appendChild(title);
      card.appendChild(text);
      card.appendChild(actions);
      wrap.appendChild(card);
      return wrap;
    }
  });
}

function onUpdate(self, engine, dt) {
  // Victory screen only.
}
